     * Set all parameters back to initial values before reading data for another plant.
     */
    protected void resetParameters()
    {
        name = null;
        maximumTemperature = 0;
        minimumTemperature = 0;
        nutritionalValue = 0;
        reproductionProbability = 0;
        maxHealth =0;
    }

